using BusinessOS.Pharmacy.Persistence.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace BusinessOS.Pharmacy.Persistence.Configurations;internal sealed class CashierShiftConfiguration:IEntityTypeConfiguration<CashierShiftEntity>{public void Configure(EntityTypeBuilder<CashierShiftEntity>b){b.ToTable("cashier_shifts");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").HasMaxLength(36).ValueGeneratedNever();b.Property(x=>x.StockLocationId).HasColumnName("stock_location_id").HasMaxLength(36).IsRequired();b.Property(x=>x.UserId).HasColumnName("user_id").HasMaxLength(64).IsRequired();b.Property(x=>x.BusinessDate).HasColumnName("business_date").IsRequired();b.Property(x=>x.Status).HasColumnName("status").HasMaxLength(24).IsRequired();b.Property(x=>x.OpeningCash).HasColumnName("opening_cash").HasPrecision(20,4).IsRequired();b.Property(x=>x.ExpectedCash).HasColumnName("expected_cash").HasPrecision(20,4);b.Property(x=>x.CountedCash).HasColumnName("counted_cash").HasPrecision(20,4);b.Property(x=>x.Variance).HasColumnName("variance").HasPrecision(20,4);b.Property(x=>x.OpenedAt).HasColumnName("opened_at").IsRequired();b.Property(x=>x.ClosedAt).HasColumnName("closed_at");b.Property(x=>x.ClosingNotes).HasColumnName("closing_notes").HasMaxLength(1000);b.Property(x=>x.CreatedAt).HasColumnName("created_at").IsRequired();b.Property(x=>x.UpdatedAt).HasColumnName("updated_at").IsRequired();b.HasIndex(x=>x.BusinessDate);b.HasIndex(x=>x.Status);b.HasIndex(x=>x.OpenedAt);b.HasIndex(x=>x.ClosedAt);b.HasIndex(x=>new{x.StockLocationId,x.BusinessDate,x.Status});b.HasIndex(x=>new{x.UserId,x.BusinessDate,x.Status});b.HasOne(x=>x.StockLocation).WithMany().HasForeignKey(x=>x.StockLocationId).OnDelete(DeleteBehavior.Restrict);}}
